export ZEEBE_BROKER_DATA_DIRECTORY=${TMPDIR:-/tmp}/vh-data CAMUNDA_DATA_SECONDARYSTORAGE_TYPE=elasticsearch CAMUNDA_DATA_SECONDARYSTORAGE_ELASTICSEARCH_URL=http://localhost:9210
